#!/usr/bin/env python3
"""Generate a sum drv over a curated safe subset.

Restricted to combos verified to work cleanly in the current main:
- archs: x86_64, aarch64, armv7l-hf, riscv64 (the 4 from the working
  hello fixture).
- compilers: modern, well-tested: gcc13/14/15, clang19/20/21.
- 2 binaries per category (smoke, gnuUtils, parsers, codecs, crypto,
  math, networking, interpreters, system, binaryAnalysis, cliTools)
  = 22 binaries total.

The matrix has known upstream-derivation bugs (e.g.
``stdenv.cc.targetPrefix`` reads in busybox/gawk/zlib that fail on
exotic compiler+arch combos like clang3_4, gcc4_x cross-archs,
armv7l-sf). Those classes are out of scope for THIS fixture.

Output: ``safe_sum_drv.txt``.
"""

from __future__ import annotations

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(PROJECT_ROOT))

from template_graph.make_sum_drv import make_sum_drv  # noqa: E402

SYS = "x86_64-linux"
OPTS = ["O0", "O2"]
ARCHS = ["x86_64", "aarch64", "armv7l-hf", "riscv64"]
COMPILERS = ["gcc13", "gcc14", "gcc15", "clang19", "clang20", "clang21"]
SUFFIX_TEMPLATE = "{comp}-{opt}-baseline-default-san-off-march-default"

BINARIES = [
    # smoke
    "hello", "busybox",
    # gnuUtils
    "coreutils", "gawk",
    # parsers
    "jq", "cjson",
    # codecs
    "libpng", "libjpeg-turbo",
    # crypto
    "openssl", "libsodium",
    # math
    "gmp", "mpfr",
    # networking
    "hiredis", "nghttp2",
    # interpreters
    "tcc", "duktape",
    # system
    "jemalloc", "mimalloc",
    # binaryAnalysis
    "capstone", "libelf",
    # cliTools
    "dash", "m4",
]

FIX_DIR = Path(__file__).parent
OUT_FILE = FIX_DIR / "safe_sum_drv.txt"


def _toolchain_attrs() -> list[str]:
    return [
        f'outputs._crossToolchainMap.{SYS}.{arch}."{comp}"'
        for arch in ARCHS for comp in COMPILERS
    ]


def _variant_attrs(binary: str) -> list[str]:
    return [
        f'outputs.dataset.{SYS}.{binary}.{arch}."{SUFFIX_TEMPLATE.format(comp=comp, opt=opt)}"'
        for arch in ARCHS for comp in COMPILERS for opt in OPTS
    ]


def main() -> int:
    n_var = len(BINARIES) * len(ARCHS) * len(COMPILERS) * len(OPTS)
    sys.stderr.write(
        f"# {len(BINARIES)} bins × {len(ARCHS)} archs × {len(COMPILERS)} comps × {len(OPTS)} opts = {n_var} attrs\n"
    )
    drv = make_sum_drv(
        flake_ref=f"git+file://{PROJECT_ROOT}",
        bash_attr=f"inputs.nixpkgs.legacyPackages.{SYS}.bash",
        toolchain_attrs=_toolchain_attrs(),
        matrices={f"matrix-{b}": _variant_attrs(b) for b in BINARIES},
        root_name="sum-root",
        toolchains_name="toolchains",
        system=SYS,
        tolerate_missing=True,
    )
    OUT_FILE.write_text(
        "# Generated by template_graph/tests/fixtures/generate_safe.py\n"
        f"# {len(BINARIES)} binaries × {len(ARCHS)} archs × {len(COMPILERS)} compilers × {len(OPTS)} opts.\n"
        f"# Binaries: {', '.join(BINARIES)}\n"
        f"# Archs:    {', '.join(ARCHS)}\n"
        f"# Compilers: {', '.join(COMPILERS)}\n"
        f"{drv}\n"
    )
    sys.stderr.write(f"# wrote {OUT_FILE}\n")
    print(drv)
    return 0


if __name__ == "__main__":
    sys.exit(main())
